1	import "server-only";
2	import type { ComparisonData } from "@/components/marketing/comparisontemplate/data";
3	import { getSettingBool, getSettingInt } from "@/lib/settings";
4	import { INSTALLABLE_FAMILIES } from "@/lib/mod-install-support";
5	import { BACKUP_FREE_KEEP } from "@/lib/backup-tiers";
6	import { SUPPORT_REPLY_WITHIN } from "@/lib/support-promise";
7	import { sections as TERMS } from "@/lib/legal/terms";
8	import { hostingPromoActive, regionFacts } from "./products-common";
9	import { annualDiscountPct } from "@/lib/annual-discount";
10	import { termPriceCents } from "@/lib/billing-terms";
11	import { usd, vpsPlans, type VpsPlan } from "./lib";
12	import { deployRegions, realTiers, sellableGames, type RealTier } from "./games-lib";
13	import { HOST_SPECS } from "./vs-hosts-data";
14	
15	/**
16	 * Comparisons with hosts the live site has no page for (game-server hosts,
17	 * more VPS hosts) — owner request 2026-09-27.
18	 *
19	 * Every competitor figure lives in ONE constant per competitor
20	 * (./vs-hosts-data.ts), each with the competitor's own page it came from and
21	 * the date it was checked; nothing is shown that isn't in one. Nxeon's side is
22	 * read from the system on every request (this file's hostCtx): Minecraft
23	 * tiers / VPS plans and prices, games sold, regions, the free Minecraft
24	 * tier, one-click mod installs, backup retention, the support promise and the
25	 * refund term. Price rows are computed from both, so a verdict can never
26	 * disagree with the numbers beside it.
27	 */
28	
29	export type Src = { url: string; checked: string };
30	export type HostCtx = {
31	  promo: boolean;
32	  regions: Awaited<ReturnType<typeof regionFacts>>;
33	  mc: RealTier[];
34	  vps: VpsPlan[];
35	  games: number;
36	  freeMc: boolean;
37	  freeMcRamGB: number;
38	  oneClickMc: boolean;
39	  backupKeep: number;
40	  support: string;
41	  nonRefundable: boolean;
42	  /** the admin annual discount (%), as checkout applies it */
43	  annualPct: number;
44	  /** player slots across the Minecraft tiers, e.g. "10 to 50" */
45	  mcSlots: string;
46	};
47	
48	/** Nxeon's side, from the system. */
49	export async function hostCtx(): Promise<HostCtx> {
50	  const [promo, regions, dRegions, vps, games, freeMc, freeRam, annualPct] = await Promise.all([
51	    hostingPromoActive(), regionFacts(), deployRegions(), vpsPlans(), sellableGames(),
52	    getSettingBool("free_minecraft_enabled", false), getSettingInt("free_minecraft_ram_mb", 1024), annualDiscountPct(),
53	  ]);
54	  const mc = await realTiers("minecraft", dRegions.map((r) => r.code));
55	  const terms = JSON.stringify(TERMS);
56	  return {
57	    promo, regions, mc, vps, games: games.length, freeMc, freeMcRamGB: Math.round((freeRam / 1024) * 10) / 10,
58	    oneClickMc: INSTALLABLE_FAMILIES.has("minecraft"), backupKeep: BACKUP_FREE_KEEP,
59	    support: `A person replies ${SUPPORT_REPLY_WITHIN}`,
60	    nonRefundable: terms.includes("fees are non-refundable"),
61	    annualPct,
62	    mcSlots: (() => { const s = mc.map((t) => t.slots).filter((n): n is number => n != null); return s.length ? (Math.min(...s) === Math.max(...s) ? `${s[0]}` : `${Math.min(...s)} to ${Math.max(...s)}`) : ""; })(),
63	  };
64	}
65	
66	type Val = string | ((x: HostCtx) => string);
67	type Verdict = "win" | "tie" | "other";
68	export type HostRow = { feature: string; me: Val; them: string; v: Verdict | ((x: HostCtx) => Verdict); note: Val; src: Src | null; when?: (x: HostCtx) => boolean };
69	export type HostPlan = { name: string; ram: number; usd: number; intro?: number; cpu?: number; disk?: number; note?: string;
70	  /** months the listed price requires (compared with Nxeon on the same term) */ term?: number };
71	
72	export type HostSpec = {
73	  key: string; name: string; short?: string; board?: string;
74	  cat: "game" | "cloud";
75	  /** brand tint (Simple Icons hex or the site's own brand colour) */
76	  color: string;
77	  /** board: YOU GAIN (≤16 chars), pass kind, pass one-liner */
78	  gain: string; type: string; edge: string;
79	  /** neutral one-liner, paraphrasing how they describe themselves (source in `site`) */
80	  kind: string;
81	  site: Src;
82	  hero: { lead: string; highlight: string; body: Val };
83	  /** their plans as listed (monthly USD), compared to Nxeon's plan of the same RAM */
84	  price?: { of: "minecraft" | "vps"; src: Src; plans: HostPlan[] };
85	  groups: { label: string; rows: HostRow[] }[];
86	  reasons: { icon: "shield" | "backup" | "support" | "bolt"; title: string; body: Val }[];
87	  chooseNxeon: Val[];
88	  chooseThem: string[];
89	  faq: { q: string; a: Val }[];
90	};
91	
92	export const HOSTS: HostSpec[] = HOST_SPECS;
93	
94	const val = (v: Val, x: HostCtx) => (typeof v === "function" ? v(x) : v);
95	const host = (u: string) => new URL(u).hostname.replace(/^www\./, "");
96	
97	/** Nxeon's plan of the same RAM (Minecraft tier or VPS plan). */
98	function nxMatch(of: "minecraft" | "vps", ram: number, x: HostCtx, term = 1) {
99	  // on a longer term, Nxeon's price for that same term (the checkout formula)
100	  const onTerm = (p: number) => (term > 1 ? termPriceCents(Math.round(p * 100), term, x.annualPct) / term / 100 : p);
101	  if (of === "minecraft") {
102	    const t = x.mc.find((m) => m.ram === ram);
103	    return t && { name: `${t.ram} GB${t.slots ? `, ${t.slots} slots` : ""}`, p: onTerm(t.p), i: term > 1 ? null : t.i, is: t.is };
104	  }
105	  const p = x.vps.find((v) => v.ram === ram);
106	  return p && { name: `${p.n} VPS`, p: onTerm(p.p), i: term > 1 ? null : p.i, is: p.it == null ? "first term" : p.it === 1 ? "first month" : `first ${p.it} months` };
107	}
108	
109	/** Price rows: their listed plan vs Nxeon's plan of the same RAM, today. */
110	function priceRows(h: HostSpec, x: HostCtx) {
111	  if (!h.price) return [];
112	  const P = h.price;
113	  const d = (n: number) => usd(Math.round(n * 100));
114	  return P.plans.flatMap((pl) => {
115	    const nx = nxMatch(P.of, pl.ram, x, pl.term);
116	    if (!nx) return [];
117	    const v: Verdict = nx.p < pl.usd * 0.97 ? "win" : nx.p > pl.usd * 1.03 ? "other" : "tie";
118	    const label = P.of === "minecraft" ? `Minecraft, ${pl.ram} GB RAM` : `VPS, ${pl.ram} GB RAM`;
119	    return [{
120	      feature: label,
121	      nxeon: `${d(nx.p)}/mo (${nx.name})${nx.i != null ? `, ${d(nx.i)} for the ${nx.is}` : ""}`,
122	      other: `${d(pl.usd)}/mo (${pl.name})${pl.intro != null ? `, ${d(pl.intro)} to start` : ""}`,
123	      verdict: v,
124	      note: `${h.name}'s ${pl.name} as listed on ${host(P.src.url)}, checked ${P.src.checked}${pl.note ? ` (${pl.note})` : ""}. Nxeon's ${nx.name} is what checkout charges today${pl.term && pl.term > 1 ? `, on the same ${pl.term}-month term` : ""}. ${pl.term && pl.term > 1 ? "Per-month prices on that term" : "Regular monthly prices"} compared.`,
125	    }];
126	  });
127	}
128	
129	/** The page's ComparisonData: sourced competitor side + the system's Nxeon side. */
130	export function buildHostData(h: HostSpec, x: HostCtx): ComparisonData {
131	  const price = priceRows(h, x);
132	  const groups = h.groups.map((g) => ({
133	    label: g.label,
134	    rows: g.rows.filter((r) => !r.when || r.when(x)).map((r) => ({
135	      feature: r.feature, nxeon: val(r.me, x), other: r.them,
136	      verdict: typeof r.v === "function" ? r.v(x) : r.v,
137	      note: val(r.note, x) + (r.src ? ` Source: ${host(r.src.url)}, checked ${r.src.checked}.` : ""),
138	    })),
139	  }));
140	  const dates = [h.site, h.price?.src, ...h.groups.flatMap((g) => g.rows.map((r) => r.src))].filter(Boolean) as Src[];
141	  const checked = [...new Set(dates.map((s) => s.checked))].join(", ");
142	  return {
143	    competitor: { name: h.name, slug: h.key, kind: h.kind },
144	    hero: { lead: h.hero.lead, highlight: h.hero.highlight, body: val(h.hero.body, x) },
145	    compareGroups: [...(price.length ? [{ label: "Price, as listed", rows: price }] : []), ...groups].filter((g) => g.rows.length),
146	    switchReasons: h.reasons.map((r) => ({ icon: r.icon, title: r.title, body: val(r.body, x) })),
147	    chooseNxeon: h.chooseNxeon.map((c) => val(c, x)),
148	    chooseOther: h.chooseThem,
149	    reviews: [],
150	    faq: h.faq.map((f) => ({ q: f.q, a: val(f.a, x) })),
151	    disclaimer: `${h.name} is a trademark of its respective owner and is not affiliated with Nxeon. ${h.name}'s figures are from its own public pages (${host(h.site.url)}), checked ${checked}; Nxeon's are read live from our catalogue. Always check each provider's current plans and pricing.`,
152	  };
153	}
