1	/**
2	 * Backup frequency & retention TIERS — the single source of truth for what each
3	 * backup tier grants (retention count, cadence) and its customer-facing copy.
4	 *
5	 * PURE module (no db, no settings imports) for the same reason as lib/extra-disk.ts:
6	 * the exact same maths is imported by the CLIENT wizard/upsell card that DISPLAYS a
7	 * price and by the server action / worker that ENFORCES + CHARGES it, so whatever
8	 * the customer sees is byte-for-byte what gets charged. Price resolution (the admin
9	 * setting) lives in the server-only lib/backup-upgrade.ts, mirroring how
10	 * extra-disk's pure maths sits apart from disk-expand's getSettingInt reader.
11	 *
12	 * MVP scope: only FREE (included, keep 2, daily) and PLUS (paid, keep 7, daily) are
13	 * SELLABLE. PRO/PREMIUM are defined for forward-compatibility but NOT offered in the
14	 * funnel — selling them needs pricing + (Premium) off-node storage this slice omits.
15	 * The MVP keeps cadence DAILY for every tier; only retention is sold.
16	 */
17	
18	export type BackupTier = "FREE" | "PLUS" | "PRO" | "PREMIUM";
19	
20	/** Legacy hardcoded retention every VPS shipped with (was worker CUSTOMER_BACKUP_KEEP=2). */
21	export const BACKUP_FREE_KEEP = 2;
22	/** Plus retention: a full week of daily restore points. */
23	export const BACKUP_PLUS_KEEP = 7;
24	
25	/** Fallback Plus price when the `backup_plus_price_cents` admin setting is unset: $2.99/mo. */
26	export const BACKUP_PLUS_DEFAULT_PRICE_CENTS = 299;
27	
28	/** Baseline cadence — daily. The MVP keeps every tier daily; only retention is sold. */
29	export const BACKUP_DAILY_INTERVAL_HOURS = 24;
30	
31	/** Tiers a customer can actually pick in the MVP funnel. */
32	export const SELLABLE_BACKUP_TIERS: BackupTier[] = ["FREE", "PLUS"];
33	
34	export type BackupTierSpec = {
35	  tier: BackupTier;
36	  /** Retention: how many recent archives are kept before the oldest are pruned. */
37	  keep: number;
38	  /** Scheduled cadence in hours. Daily across the board in the MVP. */
39	  intervalHours: number;
40	  /** Off-node/offsite durable copy. Always false in the MVP (Premium-only, deferred). */
41	  offsite: boolean;
42	  /** Short customer-facing name. */
43	  label: string;
44	  /** One-line description of what the tier keeps. */
45	  blurb: string;
46	  /** Whether this tier is offered in the funnel today. */
47	  sellable: boolean;
48	};
49	
50	/** The tier -> {keep, cadence, offsite, copy} mapping. The ONE place this is defined. */
51	export function backupTierSpec(tier: BackupTier): BackupTierSpec {
52	  switch (tier) {
53	    case "PLUS":
54	      return {
55	        tier,
56	        keep: BACKUP_PLUS_KEEP,
57	        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
58	        offsite: false,
59	        label: "Plus",
60	        blurb: `Keep the last ${BACKUP_PLUS_KEEP} daily backups — a full week of restore points.`,
61	        sellable: true,
62	      };
63	    case "PRO":
64	      return {
65	        tier,
66	        keep: 14,
67	        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
68	        offsite: false,
69	        label: "Pro",
70	        blurb: "Keep two weeks of daily restore points.",
71	        sellable: false,
72	      };
73	    case "PREMIUM":
74	      return {
75	        tier,
76	        keep: 30,
77	        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
78	        offsite: true,
79	        label: "Premium",
80	        blurb: "Keep a month of restore points with an off-node copy.",
81	        sellable: false,
82	      };
83	    case "FREE":
84	    default:
85	      return {
86	        tier: "FREE",
87	        keep: BACKUP_FREE_KEEP,
88	        intervalHours: BACKUP_DAILY_INTERVAL_HOURS,
89	        offsite: false,
90	        label: "Standard",
91	        blurb: `Keep the last ${BACKUP_FREE_KEEP} daily backups. Included free.`,
92	        sellable: true,
93	      };
94	  }
95	}
96	
97	/** Coerce arbitrary input (form value / round-tripped JSON) to a known tier; unknown => FREE. */
98	export function normalizeBackupTier(v: unknown): BackupTier {
99	  return v === "PLUS" || v === "PRO" || v === "PREMIUM" ? v : "FREE";
100	}
101	
102	/**
103	 * The retention count the worker enforces for a row: an explicit per-row override
104	 * (`backupKeep`) wins, else the tier default. The single definition the VPS backup
105	 * executor's prune step reads.
106	 */
107	export function resolveBackupKeep(tier: BackupTier, keepOverride: number | null | undefined): number {
108	  if (keepOverride != null && keepOverride > 0) return Math.round(keepOverride);
109	  return backupTierSpec(tier).keep;
110	}
111	
112	/**
113	 * Monthly price (integer cents) of a tier given the admin-tunable Plus price. PURE
114	 * so the wizard preview, the order charge and the renewal charge all derive the
115	 * SAME number (the display===charge invariant). Only PLUS is paid in the MVP; every
116	 * other tier is $0 here (PRO/PREMIUM are not sold, FREE is included).
117	 */
118	export function backupTierMonthlyCents(tier: BackupTier, plusCents: number): number {
119	  const p = Math.max(0, Math.round(plusCents));
120	  return tier === "PLUS" ? p : 0;
121	}
