1	import { execFile } from "node:child_process";
2	import { promisify } from "node:util";
3	import { db } from "./db";
4	import { ovh, ovhApi, ovhConfigured } from "./ovh";
5	import { hetznerApi, hetznerConfigured } from "./hetzner";
6	import { SANDBOX, sandboxIp, sandboxMac } from "./sandbox";
7	import { getSettingInt } from "./settings";
8	import { agentHasLiveDnatRule } from "./node-agent";
9	import type { NodeProvider } from "@prisma/client";
10	
11	const execFileP = promisify(execFile);
12	
13	/**
14	 * Is this address already the target of a live DNAT rule on ITS OWN node?
15	 * Some infrastructure (the shared-hosting node, VM 200) reaches its dedicated
16	 * IP entirely through a whole-IP DNAT rule to an internal address — it has no
17	 * OVH Virtual MAC at all, so the MAC-based check above cannot see it. A real
18	 * incident: this exact IP was one query away from being handed to a game
19	 * server because "no Virtual MAC bound" was mistaken for "free" — it was
20	 * actively carrying production hosting traffic via `iptables -t nat`. Treat
21	 * any address with a live DNAT target as claimed, unconditionally.
22	 *
23	 * Dispatches by node: the primary's own local iptables (unchanged), or the
24	 * owning node's agent for anyone else — this used to always check the LOCAL
25	 * host regardless of which node `address` actually belongs to, which for a
26	 * non-primary node's pool checks the wrong machine's kernel entirely and
27	 * could double-allocate an address that's actually already claimed there.
28	 */
29	async function hasLiveDnatRule(node: NodeRow, address: string): Promise<boolean> {
30	  if (!node.isPrimary) {
31	    try {
32	      return await agentHasLiveDnatRule(node, address);
33	    } catch {
34	      // Agent unreachable/not configured — same fail-open reasoning as the
35	      // local case below: a false "not claimed" is recoverable (the Virtual
36	      // MAC check and the existing DB row are the other guards), a sync that
37	      // silently no-ops for an entire node's pool forever is not.
38	      return false;
39	    }
40	  }
41	  try {
42	    const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"]);
43	    return stdout.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
44	  } catch {
45	    // iptables unreadable (permissions, not present, sandboxed test env) — fail
46	    // closed is wrong here (it would make every sync a no-op); fail to "not
47	    // claimed by this specific check" and rely on the Virtual MAC check plus
48	    // the existing DB row remaining authoritative for anything already tracked.
49	    return false;
50	  }
51	}
52	
53	/**
54	 * What OVH actually bills per additional/failover IPv4 in the pool, in cents.
55	 * Single source of truth for both the IP-pool page's "OVH cost" stat and the
56	 * admin Accounting dashboard's auto-pulled infrastructure expense line — before
57	 * this it existed only as a copy of the same number hardcoded on the IP page.
58	 */
59	export const OVH_IP_UNIT_COST_CENTS = 239;
60	
61	/** Hetzner's "additional IP" rate, confirmed live in the Robot panel 2026-09-15. */
62	export const HETZNER_IP_UNIT_COST_CENTS = 200;
63	
64	/**
65	 * Fallback monthly price for a dedicated IPv4. Defaults to 0 — a dedicated IP is
66	 * INCLUDED on every plan (its cost is folded into plan pricing, as the marketing
67	 * pages state). The admin `dedicated_ip_price_cents` setting is the source of
68	 * truth; use `dedicatedIpMonthlyCents()` in billing paths, not this constant.
69	 */
70	export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 0);
71	
72	/**
73	 * The monthly dedicated-IP surcharge actually charged, from the admin setting
74	 * (`dedicated_ip_price_cents`, default 0 = included). Single source of truth for
75	 * every order/renewal/display path so they can never disagree.
76	 *
77	 * NORMALISED to a non-negative whole number of cents, exactly as
78	 * `extraDiskPerGbCents` (lib/disk-expand.ts) already does for the other
79	 * admin-priced add-on. `getSettingInt` is a raw `Number()` of whatever string sits
80	 * in the `Setting` row, so it happily returns 2.5 or -500. This value is multiplied
81	 * by the term length straight into `chargeCents` (lib/order.ts orderQuote) and into
82	 * `renewalCharge`, and from there into `debitWallet`, `unit_amount` and an Invoice
83	 * row — every one of which is integer cents. A fractional setting produced a
84	 * fractional charge that failed at Stripe or Prisma AFTER the customer had agreed
85	 * to it; a negative one silently discounted the plan.
86	 */
87	export async function dedicatedIpMonthlyCents(): Promise<number> {
88	  const v = await getSettingInt("dedicated_ip_price_cents", DEDICATED_IP_PRICE_CENTS);
89	  return Math.max(0, Math.round(v));
90	}
91	/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
92	export const DEDICATED_IP_BUFFER = Number(process.env.DEDICATED_IP_BUFFER ?? 2);
93	
94	/** OVH failover gateway = the host's /24 gateway (…​.254). OVH-specific — every
95	 *  additional/failover IP on an OVH dedicated server shares this one convention. */
96	function ovhGatewayFor(nodePublicIp: string): string {
97	  const parts = nodePublicIp.split(".");
98	  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
99	}
100	
101	/** Back-compat wrapper for any caller still expecting the old single-node signature. */
102	export function ovhGateway(): string {
103	  return ovhGatewayFor(process.env.PUBLIC_IP ?? "51.79.162.96");
104	}
105	
106	type NodeRow = {
107	  id: string;
108	  name: string;
109	  provider: NodeProvider;
110	  publicIp: string;
111	  providerServerId: string | null;
112	  isPrimary: boolean;
113	  agentPort: number;
114	  agentTokenEnc: string | null;
115	};
116	
117	const NODE_ROW_SELECT = {
118	  id: true,
119	  name: true,
120	  provider: true,
121	  publicIp: true,
122	  providerServerId: true,
123	  isPrimary: true,
124	  agentPort: true,
125	  agentTokenEnc: true,
126	} as const;
127	
128	/** Resolve the Node a dedicated-IP operation should act against: the id passed
129	 *  in explicitly, else the primary node — same fallback shape as
130	 *  worker/index.ts's nodeFor(), so single-node callers need no changes at all. */
131	async function resolveNode(nodeId?: string): Promise<NodeRow | null> {
132	  if (nodeId) {
133	    return db.node.findUnique({ where: { id: nodeId }, select: NODE_ROW_SELECT });
134	  }
135	  return db.node.findFirst({ where: { isPrimary: true }, select: NODE_ROW_SELECT });
136	}
137	
138	/** Is the right provider API even configured for this node? Dispatches by
139	 *  provider so a Hetzner-hosted server never silently falls through to
140	 *  checking whether OVH happens to be configured (the real bug this fixes —
141	 *  worker/index.ts used to gate purely on ovhConfigured(), with no node
142	 *  awareness at all). */
143	export async function dedicatedIpProviderConfigured(nodeId?: string): Promise<boolean> {
144	  const node = await resolveNode(nodeId);
145	  if (!node) return false;
146	  return node.provider === "HETZNER" ? hetznerConfigured() : ovhConfigured();
147	}
148	
149	/**
150	 * Pull additional/failover IPv4 addresses routed to a node's server from its
151	 * provider and upsert them into the pool. The host's own primary IP is never
152	 * poolable. Defaults to the primary (OVH) node when no `nodeId` is given —
153	 * identical behavior to before this file supported more than one node.
154	 */
155	export async function syncDedicatedIpPool(nodeId?: string): Promise<{ imported: number; total: number }> {
156	  if (SANDBOX) return { imported: 0, total: 0 };
157	  const node = await resolveNode(nodeId);
158	  if (!node || !node.providerServerId) return { imported: 0, total: 0 };
159	
160	  if (node.provider === "HETZNER") return syncHetznerPool(node);
161	  return syncOvhPool(node);
162	}
163	
164	async function syncOvhPool(node: NodeRow): Promise<{ imported: number; total: number }> {
165	  if (!ovhConfigured()) return { imported: 0, total: 0 };
166	  const SERVER = node.providerServerId!;
167	  const primary = node.publicIp;
168	  const blocks: string[] = await ovhApi.ips();
169	  let imported = 0;
170	  for (const block of blocks) {
171	    if (block.includes(":")) continue; // IPv6 handled separately
172	    let info: any;
173	    try {
174	      info = await ovhApi.ipInfo(block);
175	    } catch {
176	      continue;
177	    }
178	    if (info?.routedTo?.serviceName !== SERVER) continue;
179	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
180	    // A /32 block is a single usable IP == the block minus the mask.
181	    const address = block.split("/")[0];
182	    if (address === primary) continue;
183	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
184	    if (!existing) {
185	      // An IP that already has a Virtual MAC bound to it on OVH's side is already
186	      // in active use by SOME VM — possibly one this app never created a Server
187	      // row for (e.g. internal infrastructure provisioned directly via the OVH
188	      // API, like the cold-email relay). A genuinely free IP has no bound MAC
189	      // yet. Importing it as FREE anyway let a real customer server collide with
190	      // an unrelated VM's network identity — never assign an IP that's already
191	      // claimed at the network layer, regardless of whether our DB knows about it.
192	      if (await findVirtualMacForIp(SERVER, address)) continue;
193	      if (await hasLiveDnatRule(node, address)) continue;
194	      // Every IP this function imports is, by construction, a spare address
195	      // OVH says is routed to us and not yet claimed at the network layer — the
196	      // pool customer orders draw from. Internal-use IPs (the cold-email relay,
197	      // an owner-operated site, the shared-hosting node) are rare, hand-provisioned
198	      // one-offs marked INTERNAL by an admin after the fact; this sync has no way
199	      // to tell them apart from a genuinely free customer IP and must not try —
200	      // it always imports as CUSTOMER (the schema default, stated here for clarity).
201	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, nodeId: node.id, status: "FREE", purpose: "CUSTOMER" } });
202	      imported++;
203	    }
204	  }
205	  const total = await db.dedicatedIp.count({ where: { nodeId: node.id } });
206	  return { imported, total };
207	}
