209	/**
210	 * Hetzner side of the sync. Hetzner's `/ip` listing already returns exactly
211	 * the single additional IPs on the account (no failover/additional type
212	 * distinction to filter like OVH's `/ip` does) — every entry not equal to the
213	 * node's own main `publicIp` is poolable.
214	 */
215	async function syncHetznerPool(node: NodeRow): Promise<{ imported: number; total: number }> {
216	  if (!hetznerConfigured()) return { imported: 0, total: 0 };
217	  let imported = 0;
218	  // The Robot API wraps each entry as `{ ip: { ip: "1.2.3.4", server_ip: ..., ... } }`,
219	  // not a flat `{ ip: "1.2.3.4" }` — confirmed live 2026-09-15, the first time this
220	  // ever ran against a real account (Hetzner credentials had never been configured
221	  // before). The old flat-shape read left `address` holding the nested object, which
222	  // Prisma's `where: { address }` rejects outright — the sync could never have
223	  // succeeded even once.
224	  const ips: Array<{ ip: { ip: string; server_ip: string } }> = await hetznerApi.ips().catch(() => []);
225	  for (const entry of ips) {
226	    const address = entry.ip?.ip;
227	    if (!address || address === node.publicIp) continue;
228	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
229	    if (existing) continue;
230	    if (await hasLiveDnatRule(node, address)) continue;
231	    await db.dedicatedIp.create({
232	      data: { address, ovhBlock: "", nodeId: node.id, status: "FREE", purpose: "CUSTOMER" },
233	    });
234	    imported++;
235	  }
236	  const total = await db.dedicatedIp.count({ where: { nodeId: node.id } });
237	  return { imported, total };
238	}
