240	/** Count of IPs actually available to hand to a customer — same eligibility as
241	 * allocateDedicatedIp's claim query; excludes admin-marked INTERNAL rows. */
242	export async function freeCount(): Promise<number> {
243	  return db.dedicatedIp.count({ where: { status: "FREE", purpose: "CUSTOMER" } });
244	}
