246	/**
247	 * The real, live monthly bill for the whole dedicated-IP pool, in cents —
248	 * every pooled IP (free or assigned) costs its PROVIDER's per-IP rate
249	 * regardless of whether a customer is using it. Consumed by the Accounting
250	 * dashboard as an automatic recurring INFRASTRUCTURE expense line so this
251	 * cost is never hand-typed and can never drift from what /admin/ips itself
252	 * shows. Priced per-provider (not a single flat OVH rate) since 2026-09-15,
253	 * the day the first real Hetzner IP was pooled at its own, cheaper rate.
254	 */
255	export async function dedicatedIpPoolMonthlyCostCents(): Promise<number> {
256	  const counts = await db.dedicatedIp.groupBy({
257	    by: ["nodeId"],
258	    _count: true,
259	  });
260	  if (counts.length === 0) return 0;
261	  const nodes = await db.node.findMany({
262	    where: { id: { in: counts.map((c) => c.nodeId).filter((id): id is string => !!id) } },
263	    select: { id: true, provider: true },
264	  });
265	  const providerById = new Map(nodes.map((n) => [n.id, n.provider]));
266	  return counts.reduce((sum, c) => {
267	    const provider = c.nodeId ? providerById.get(c.nodeId) : undefined;
268	    const rate = provider === "HETZNER" ? HETZNER_IP_UNIT_COST_CENTS : OVH_IP_UNIT_COST_CENTS;
269	    return sum + c._count * rate;
270	  }, 0);
271	}
