273	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
274	async function findVirtualMacForIp(server: string, address: string): Promise<string | null> {
275	  const macs: string[] = await ovh("GET", `/dedicated/server/${server}/virtualMac`).catch(() => []);
276	  for (const m of macs) {
277	    const ips: string[] = await ovh("GET", `/dedicated/server/${server}/virtualMac/${m}/virtualAddress`).catch(() => []);
278	    if (ips.includes(address)) return m;
279	  }
280	  return null;
281	}
