359	/**
360	 * The gateway a VM should use for this IP. OVH: the well-known "/24 -> .254"
361	 * convention, same for every additional IP on that node. Hetzner: NOT a
362	 * fixed formula — Hetzner assigns a distinct gateway per single additional
363	 * IP (confirmed against Hetzner's own docs this session: additional IP
364	 * SUBNETS route via the server's main IP with no separate gateway, but
365	 * single additional IPs each come with their own gateway address) — read it
366	 * from Hetzner's own `/ip/{ip}` response rather than guessing a formula.
367	 * NOTE: the exact response field name below (`gateway`) hasn't been verified
368	 * against a real Hetzner additional IP yet (none exist in the pool at the
369	 * time this was written) — confirm it the first time this path actually
370	 * runs, before trusting it for a real customer's network config.
371	 */
372	async function gatewayFor(node: NodeRow, address: string): Promise<string> {
373	  if (node.provider === "OVH") return ovhGatewayFor(node.publicIp);
374	  try {
375	    const info = await hetznerApi.ipInfo(address);
376	    if (info?.ip?.gateway) return info.ip.gateway as string;
377	  } catch {
378	    /* fall through */
379	  }
380	  return node.publicIp; // best-effort fallback; see doc comment above
381	}
