420	/** Set reverse DNS (PTR) for a dedicated IP — dispatches to the owning node's provider. */
421	export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
422	  const ip = await db.dedicatedIp.findUnique({ where: { address }, include: { node: true } });
423	  if (!ip) return;
424	  if (ip.node.provider === "HETZNER") {
425	    if (!hetznerConfigured()) return;
426	    await hetznerApi.setReverse(address, reverse);
427	  } else {
428	    if (!ovhConfigured()) return;
429	    await ovhApi.setReverse(`${address}/32`, address, reverse);
430	  }
431	  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
432	}
