1	/**
2	 * Shared per-server DEDICATED IP purchase core — the money path for adding a
3	 * dedicated public IPv4 to a server that does NOT already have one.
4	 *
5	 * Mirrors lib/disk-expand.ts (which itself mirrors lib/resize.ts) line-for-line
6	 * in shape: a pure `*Quote` function re-validated by `apply*`, used by both the
7	 * wallet flow (lib/actions-dedicated-ip.ts) and the Stripe confirm route so a
8	 * paid checkout can apply the purchase immediately. Plain server module (NOT
9	 * "use server").
10	 *
11	 * ─── WHY THIS CANNOT DOUBLE-CHARGE ──────────────────────────────────────────
12	 * Identical argument to lib/disk-expand.ts: one quote function, one wallet debit
13	 * inside the same transaction that creates the job, and the card path credits
14	 * only the card remainder before debiting the full proration on confirm.
15	 *
16	 * ─── ROLLBACK SAFETY (real infra, real money) ───────────────────────────────
17	 * The actual IP claim + OVH Virtual MAC creation + Proxmox network reconfig all
18	 * happen in the WORKER (`ASSIGN_DEDICATED_IP`, worker/index.ts), never here —
19	 * exactly like DISK_EXPAND never touches Proxmox synchronously inside the
20	 * action. That keeps "charge" and "allocate" as two separate steps that can
21	 * each fail independently without corrupting the other:
22	 *   - If nothing is charged, no job is ever created (both happen in one
23	 *     `$transaction`), so nothing is ever allocated.
24	 *   - If the job's `allocateDedicatedIp` call can't claim a pool IP (or OVH
25	 *     errors), it throws BEFORE touching the DB (see lib/dedicated-ip.ts's own
26	 *     rollback-on-failure) and the job fails/retries; a terminal failure is
27	 *     refunded by `reconcileFailedJob` in worker/index.ts, mirroring RESIZE.
28	 */
29	import { db } from "./db";
30	import { debitWallet, InsufficientBalanceError } from "./wallet";
31	import { invoiceCreateData } from "./invoices";
32	import { remainingMonths } from "./proration";
33	import { extraDiskProrateCents } from "./extra-disk";
34	import { dedicatedIpMonthlyCents, freeCount } from "./dedicated-ip";
35	
36	export class DedicatedIpPurchaseError extends Error {}
37	
38	function loadServer(serverId: string) {
39	  return db.server.findUnique({ where: { id: serverId }, include: { dedicatedIp: true } });
40	}
41	
42	type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
43	
44	export type DedicatedIpQuote = {
45	  server: QuotedServer;
46	  monthlyCents: number;
47	  /** One-off charge for the remainder of the CURRENT paid term. */
48	  prorateCents: number;
49	};
50	
51	/**
52	 * Validate a dedicated-IP purchase and compute the prorated charge over the
53	 * ACTUAL remaining duration — identical maths to `diskExpandQuote` (a flat
54	 * monthly add-on × every remaining month; null expiresAt on free/admin servers
55	 * => 0). Throws DedicatedIpPurchaseError with a user-facing message on any
56	 * guard failure. Does NOT check ownership — callers must do that.
57	 */
58	export async function dedicatedIpPurchaseQuote(serverId: string): Promise<DedicatedIpQuote> {
59	  const server = await loadServer(serverId);
60	  if (!server) throw new DedicatedIpPurchaseError("Not found");
61	  if (server.dedicatedIp) {
62	    throw new DedicatedIpPurchaseError("This server already has a dedicated IP.");
63	  }
64	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
65	    throw new DedicatedIpPurchaseError("Server is busy — wait for the current operation to finish.");
66	  }
67	  if (!server.vmid) throw new DedicatedIpPurchaseError("This server hasn't finished provisioning yet.");
68	
69	  // A DB-level check only — the authoritative claim happens atomically in the
70	  // worker (allocateDedicatedIp). This just avoids charging a customer for a
71	  // pool we already know is empty.
72	  const available = await freeCount();
73	  if (available <= 0) {
74	    throw new DedicatedIpPurchaseError(
75	      "No dedicated IPs are available in the pool right now — please contact support and we'll get one allocated.",
76	    );
77	  }
78	
79	  const monthlyCents = await dedicatedIpMonthlyCents();
80	  let prorateCents = 0;
81	  if (!server.isFree && server.expiresAt) {
82	    // Reuses the generic "flat monthly amount × remaining months" prorate
83	    // formula lib/extra-disk.ts already owns for the disk add-on — it is not
84	    // disk-specific despite the name (`Math.max(0, Math.round(monthly * months))`),
85	    // and this is exactly the shape of a flat monthly surcharge like the
86	    // dedicated-IP price, so it is reused rather than redefined a third time.
87	    prorateCents = extraDiskProrateCents(monthlyCents, remainingMonths(server.expiresAt, Date.now()));
88	  }
89	  return { server, monthlyCents, prorateCents };
90	}
91	
92	/**
93	 * Apply the purchase: (optionally) debit the wallet for the prorated charge,
94	 * record the wallet transaction + PAID invoice, and queue the
95	 * ASSIGN_DEDICATED_IP job the worker performs against Proxmox/OVH. Re-validates
96	 * every guard so it is safe to call from the unauthenticated confirm route.
97	 * Throws DedicatedIpPurchaseError on any guard failure.
98	 *
99	 * `chargeCents` overrides the recomputed proration — the paid path passes the
100	 * exact amount the customer paid into their wallet at checkout so the debit
101	 * here nets to zero against that credit (mirrors lib/disk-expand.ts).
102	 */
103	export async function applyDedicatedIpPurchase(opts: {
104	  serverId: string;
105	  actorUserId: string;
106	  chargeCents?: number;
107	}): Promise<void> {
108	  const quote = await dedicatedIpPurchaseQuote(opts.serverId);
109	  const { server, monthlyCents } = quote;
110	  const prorateCents = opts.chargeCents ?? quote.prorateCents;
111	
112	  const pending = await db.job.count({
113	    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
114	  });
115	  if (pending > 0) throw new DedicatedIpPurchaseError("Another operation is already in progress on this server.");
116	
117	  try {
118	    await db.$transaction(async (tx) => {
119	      if (prorateCents > 0) {
120	        await debitWallet(tx, server.userId, prorateCents);
121	        await tx.walletTransaction.create({
122	          data: {
123	            userId: server.userId,
124	            amountCents: -prorateCents,
125	            description: `Dedicated IP add-on (prorated) — ${server.hostname}`,
126	          },
127	        });
128	        await tx.invoice.create({
129	          data: invoiceCreateData({
130	            userId: server.userId,
131	            description: `Dedicated IP add-on (prorated) — ${server.hostname}`,
132	            status: "PAID",
133	            lineItems: [
134	              {
135	                description:
136	                  `Dedicated IP — prorated for remaining term (${server.hostname}). ` +
137	                  `Renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
138	                qty: 1,
139	                unitCents: prorateCents,
140	                amountCents: prorateCents,
141	              },
142	            ],
143	          }),
144	        });
145	      }
146	      // Record the amount charged AND the monthly rate on the job so the worker
147	      // can deliver it, and so a terminal failure can be REVERSED (refund the
148	      // charge, release any IP it managed to claim) — money is committed here,
149	      // before the job runs.
150	      await tx.job.create({
151	        data: {
152	          type: "ASSIGN_DEDICATED_IP",
153	          serverId: server.id,
154	          payload: { prorateCents, monthlyCents } as any,
155	        },
156	      });
157	      await tx.auditLog.create({
158	        data: {
159	          userId: opts.actorUserId,
160	          action: "server.dedicated_ip_purchase",
161	          detail: `${server.id} prorate=${prorateCents} monthly=${monthlyCents}`,
162	        },
163	      });
164	    });
165	  } catch (e) {
166	    if (e instanceof InsufficientBalanceError) {
167	      throw new DedicatedIpPurchaseError("Insufficient balance — top up your wallet first.");
168	    }
169	    throw e;
170	  }
171	}
